<?php
declare(strict_types=1);
require_once __DIR__.'/tenant.php';
require_once __DIR__.'/activity.php';
$user=requireLogin();$pdo=activityDb();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);
if(!$id){http_response_code(400);exit('Ongeldig e-mailbericht.');}
$stmt=$pdo->prepare('SELECT e.*,a.Label,a.EmailAddress FROM EmailBerichten e JOIN EmailAccounts a ON a.EmailAccountID=e.EmailAccountID WHERE e.EmailBerichtID=?');$stmt->execute([$id]);$mail=$stmt->fetch(PDO::FETCH_ASSOC);
if(!$mail){http_response_code(404);exit('E-mailbericht niet gevonden.');}
function ev(string $value):string{return htmlspecialchars($value,ENT_QUOTES,'UTF-8');}
function cleanMail(string $body):string{$body=str_replace(["\r\n","\r"],"\n",trim($body));if(substr_count($body,"\n")<2)$body=preg_replace('/\s+>\s+/u',"\n> ",$body)??$body;$body=preg_replace('/^(?:>\s*)+/m','',$body)??$body;$body=preg_replace('/\s*<mailto:[^>]+>/iu','',$body)??$body;$body=preg_replace('/\n{3,}/u',"\n\n",$body)??$body;return trim($body);}
function mailHtml(string $body):string{$html='';$separator=false;foreach(explode("\n",cleanMail($body)) as $line){$trim=trim($line);if(preg_match('/^(?:Begin doorgestuurd bericht:|-{2,}\s*(?:Oorspronkelijk|Doorgestuurd) bericht\s*-{2,}|Op .{0,180} schreef .{0,180}:)$/iu',$trim)){$html.='<hr class="message-separator"><div class="forward-label">'.ev(trim($trim,'- ')).'</div>';$separator=true;continue;}if(preg_match('/^(Van|Aan|Datum|Verzonden|Onderwerp|Cc|Kopie|From|To|Date|Sent|Subject):\s*(.*)$/iu',$trim,$m)){if(in_array(mb_strtolower($m[1]),['van','from'],true)&&!$separator)$html.='<hr class="message-separator">';$html.='<div class="quoted-header"><strong>'.ev($m[1]).':</strong> '.ev($m[2]).'</div>';$separator=false;continue;}$html.=$trim===''?'<div class="blank">&nbsp;</div>':'<div>'.ev($line).'</div>';$separator=false;}return $html;}
$full=cleanMail((string)$mail['BodyText']);$attachments=array_values(array_filter(array_map('trim',explode(',',(string)$mail['AttachmentNames']))));recordActivity($pdo,$user,'e-mailbron-geopend','e-mail','e-mailbericht',(string)$id,'Lokale e-mailbron geopend');
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=ev((string)$mail['Subject'])?></title><style>:root{--line:#d7e0e8}body{margin:0;background:#f3f6f9;color:#17202a;font:15px system-ui,-apple-system,Segoe UI,Arial}.wrap{max-width:950px;margin:25px auto;padding:0 14px}.card{background:#fff;border:1px solid var(--line);border-radius:10px;padding:20px}.meta{color:#607080;line-height:1.65;border-bottom:1px solid var(--line);padding-bottom:12px}.message{line-height:1.55;margin-top:18px;font-size:16px;overflow-wrap:anywhere}.message .blank{height:.7em}.quoted-header{padding:2px 0}.message-separator{border:0;border-top:2px solid #aebdca;margin:24px 0 10px}.forward-label{font-weight:700;color:#526474;margin-bottom:7px}.back{display:inline-block;margin-bottom:12px;color:#174f8e;font-weight:700}.attachments{margin:15px 0;padding:12px;background:#eef5fc;border-radius:8px}.chip{display:inline-block;margin:4px 5px 0 0;padding:5px 9px;background:#fff;border:1px solid #bfd0e1;border-radius:14px;color:#174f8e;text-decoration:none}.empty{color:#607080}</style></head><body><main class="wrap"><a class="back" href="assistant.php" onclick="if(history.length>1){event.preventDefault();history.back();}">← Terug naar dezelfde zoekresultaten</a><article class="card"><h1><?=ev((string)$mail['Subject'])?></h1><div class="meta"><strong>Van:</strong> <?=ev((string)$mail['Sender'])?><br><strong>Aan:</strong> <?=ev((string)$mail['Recipients'])?><br><strong>Datum:</strong> <?=ev((string)$mail['SentAt'])?><br><strong>Mailbox / map:</strong> <?=ev((string)$mail['Label'])?> · <?=ev((string)$mail['FolderName'])?></div><section class="attachments"><strong>📎 Bijlagen</strong><br><?php if($attachments):?><?php foreach($attachments as $attachment):?><?php $ext=mb_strtolower(pathinfo($attachment,PATHINFO_EXTENSION));$inline=in_array($ext,['pdf','png','jpg','jpeg','gif','webp','txt'],true);?><a class="chip" href="email_attachment.php?mail=<?=$id?>&amp;name=<?=rawurlencode($attachment)?><?=$inline?'&amp;view=1':''?>"<?php if(!$inline):?> download<?php endif;?>><?=ev($attachment)?></a><?php endforeach;?><?php else:?><span class="empty">Bij dit geïndexeerde bericht zijn geen bijlagen aangetroffen.</span><?php endif;?></section><div class="message"><?=mailHtml($full)?></div></article></main></body></html>
